ont-family:wf_segoe-ui_normal}\r\np.MsoNormal, li.MsoNormal, div.MsoNormal\r\n	{margin:0cm;\r\n	font-size:12.0pt;\r\n	font-family:\"Aptos\",sans-serif}\r\na:link, span.MsoHyperlink\r\n	{color:blue;\r\n	text-decoration:underline}\r\nspan.EmailStyle21\r\n	{font-family:\"Century Gothic\",sans-serif;\r\n	color:windowtext}\r\np.m3038356942523821851xmsonormal, li.m3038356942523821851xmsonormal, div.m3038356942523821851xmsonormal\r\n	{margin-right:0cm;\r\n	margin-left:0cm;\r\n	font-size:12.0pt;\r\n	font-family:\"Aptos\",sans-serif}\r\n.MsoChpDefault\r\n	{font-size:10.0pt}\r\n@page WordSection1\r\n	{margin:72.0pt 72.0pt 72.0pt 72.0pt}\r\ndiv.WordSection1\r\n	{}\r\n-->\r\n</style></head><body lang=\"EN-ZA\" link=\"blue\" vlink=\"purple\" style=\"word-wrap:break-word\"><div class=\"WordSection1\"><p class=\"m3038356942523821851xmsonormal\"><span style=\"font-family:&quot;Century Gothic&quot;,sans-serif\">Afternoon</span></p><p class=\"m3038356942523821851xmsonormal\"><span style=\"font-family:&quot;Century Gothic&quot;,sans-serif\">Please note that you no longer have death, disability and funeral cover as your employer was in arrears and Sanlam cancelled the Risk Cover, the employer was requested to advise each member.</span></p><p class=\"m3038356942523821851xmsonormal\"><span style=\"font-family:&quot;Century Gothic&quot;,sans-serif\">The employer owes Sanlam Late Payment Interest which has not been settled.</span></p><p class=\"m3038356942523821851xmsonormal\"><span style=\"font-family:&quot;Century Gothic&quot;,sans-serif\">The Employer is currently in Arrears and has not paid March 2026 and April 2026 is due by 5<sup>th</sup> May.</span></p><p class=\"m3038356942523821851xmsonormal\"><span style=\"font-family:&quot;Century Gothic&quot;,sans-serif\">Password to access document is your id number.&nbsp;</span></p><div><div><div><div><div style=\"border:none; border-bottom:solid #E5E5E5 1.0pt; padding:0cm 0cm 19.0pt 0cm; background:white\"><p class=\"MsoNormal\" style=\"background:white; border:none; padding:0cm\"><span lang=\"EN-US\" style=\"font-size:9.0pt; font-family:&quot;Century Gothic&quot;,sans-serif; color:black\">Please note that no documents should be forwarded to a personal inbox or to that of any other individual, but rather to the central dispatch e-mail address <a href=\"mailto:Unity@futurasa.co.za\">Unity@futurasa.co.za</a> &nbsp;This process allows us to keep a proper track record and audit trail of all documents received and reduces the risk of not processing important information timeously.</span><span lang=\"EN-US\" style=\"font-size:9.0pt; font-family:&quot;Century Gothic&quot;,sans-serif\"></span></p><p class=\"MsoNormal\" style=\"line-height:20.65pt; background:white; border:none; padding:0cm\"><span style=\"font-family:&quot;Century Gothic&quot;,sans-serif; color:black; background:white\">Regards</span></p><p class=\"MsoNormal\" style=\"line-height:20.65pt; background:white; border:none; padding:0cm\"><b><span style=\"font-family:&quot;Century Gothic&quot;,sans-serif; color:#63BE60; background:white\">Merril Fennessy</span></b></p></div><p class=\"MsoNormal\" style=\"background:white\"><span style=\"font-family:&quot;Century Gothic&quot;,sans-serif; color:black; background:white\">Client Relations Manager Sanlam Unity Umbrella Fund</span></p><table class=\"MsoNormalTable\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" style=\"background:white; border-collapse:collapse\"><tbody><tr><td width=\"130\" rowspan=\"4\" valign=\"top\" style=\"width:97.8pt; border:none; border-right:solid #A5A5A5 1.0pt; padding:0cm 5.4pt 0cm 5.4pt\"><p class=\"MsoNormal\"><span style=\"color:black\"><a href=\"https://www.futurasa.co.za/\" target=\"_blank\"><span style=\"font-family:&quot;Century Gothic&quot;,sans-serif; color:black; text-decoration:none\"><img border=\"0\" width=\"130\" height=\"78\" id=\"Picture_x0020_1521147831\" src=\"cid:image002.png@01DCDCA7.584BE410\" style=\"width:1.3541in; height:.8125in\"></span></a></span><s